// src/hooks/useIndicatorWorker.ts
import { useEffect, useState } from 'react';

export const useIndicatorWorker = (ticks: PriceTick[]) => {
  const [indicators, setIndicators] = useState<IndicatorData | null>(null);

  useEffect(() => {
    const worker = new Worker(new URL('../workers/indicatorWorker.ts', import.meta.url));

    worker.onmessage = (event: MessageEvent<IndicatorData>) => {
      setIndicators(event.data);
    };

    worker.postMessage({ ticks, period: 14 });
    return () => worker.terminate();
  }, [ticks]);

  return indicators;
};
