// src/features/watchlist/VirtualStockTable.tsx
import { useVirtualizer } from '@tanstack/react-virtual';
import React, { useRef } from 'react';

export const VirtualStockTable: React.FC<{ rows: StockRow[] }> = ({ rows }) => {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 52,
    overscan: 3,
  });

  return (
    <div ref={parentRef} className="h-[600px] overflow-auto border border-white/10 rounded-xl">
      <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, position: 'relative' }}>
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const item = rows[virtualRow.index];
          return (
            <div
              key={item.symbol}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: `${virtualRow.size}px`,
                transform: `translateY(${virtualRow.start}px)`,
              }}
            >
              <StockTableRow data={item} />
            </div>
          );
        })}
      </div>
    </div>
  );
};
