// Memoized row component with custom comparator
export const StockTableRow = React.memo<StockRowProps>(({ data }) => {
  return (
    <div className="flex items-center justify-between px-4 py-3 hover:bg-white/5 transition-colors">
      <span className="font-bold text-white">{data.symbol}</span>
      <span className={data.change >= 0 ? 'text-emerald-400' : 'text-rose-400'}>
        ${data.price.toFixed(2)} ({data.change > 0 ? '+' : ''}{data.change.toFixed(2)}%)
      </span>
    </div>
  );
}, (prev, next) => {
  return prev.data.price === next.data.price && prev.data.change === next.data.change;
});
